-- SmartSpace Data Export from SQLite to Supabase PostgreSQL
-- Run this script in the Supabase SQL Editor AFTER executing schema-supabase.sql

BEGIN;

-- Data for table: users

-- Data for table: rooms

-- Data for table: timetable

-- Data for table: bookings

-- Data for table: notifications

-- Data for table: recent_views

-- Data for table: navigation_revisions

-- Synchronize identity sequence counters with imported maximum IDs
SELECT setval(pg_get_serial_sequence('users', 'user_id'), COALESCE((SELECT MAX(user_id) FROM users), 1));
SELECT setval(pg_get_serial_sequence('rooms', 'room_id'), COALESCE((SELECT MAX(room_id) FROM rooms), 1));
SELECT setval(pg_get_serial_sequence('timetable', 'timetable_id'), COALESCE((SELECT MAX(timetable_id) FROM timetable), 1));
SELECT setval(pg_get_serial_sequence('bookings', 'booking_id'), COALESCE((SELECT MAX(booking_id) FROM bookings), 1));
SELECT setval(pg_get_serial_sequence('maintenance', 'maintenance_id'), COALESCE((SELECT MAX(maintenance_id) FROM maintenance), 1));
SELECT setval(pg_get_serial_sequence('notifications', 'notification_id'), COALESCE((SELECT MAX(notification_id) FROM notifications), 1));
SELECT setval(pg_get_serial_sequence('navigation_revisions', 'revision_id'), COALESCE((SELECT MAX(revision_id) FROM navigation_revisions), 1));

COMMIT;
